import React, { useState } from 'react';
import BlocoEtapaVisual from './BlocoEtapaVisual';

export default function EditorEtapasAvancado_Modular() {
  const [fluxos, setFluxos] = useState([
    { id: 1, nome: "Atendimento Loja", etapas: 4, ativo: true, atualizado: "13/04/2025 09:45" },
    { id: 2, nome: "Suporte Noturno", etapas: 3, ativo: false, atualizado: "12/04/2025 21:18" },
    { id: 3, nome: "Agendamentos Finais", etapas: 5, ativo: false, atualizado: "10/04/2025 14:10" }
  ]);
  const [fluxoSelecionado, setFluxoSelecionado] = useState({ id: 1, nome: "Atendimento Loja", etapas: 4, ativo: true, atualizado: "13/04/2025 09:45" });
  const [modoAvancado, setModoAvancado] = useState(false);

  const ativarFluxo = (id) => {
    const atualizados = fluxos.map(f => {
      return {
        ...f,
        ativo: f.id === id
      };
    });
    setFluxos(atualizados);
    setFluxoSelecionado(atualizados.find(f => f.id === id));
  };

  const novoFluxo = () => {
    const novo = {
      id: Date.now(),
      nome: `Novo Fluxo ${fluxos.length + 1}`,
      etapas: 0,
      ativo: false,
      atualizado: new Date().toLocaleString()
    };
    setFluxos([...fluxos, novo]);
  };

  return (
    <div className="flex min-h-screen bg-gray-100 font-sans">
      <aside className="w-72 bg-white shadow px-4 py-6 border-r overflow-y-auto">
        <h2 className="text-lg font-bold mb-4">Meus Fluxos</h2>
        <ul className="space-y-3">
          {fluxos.map((fluxo) => (
            <li
              key={fluxo.id}
              className={`p-3 rounded border cursor-pointer ${fluxo.ativo ? 'bg-blue-50 border-blue-400' : 'bg-gray-50'}`}
              onClick={() => setFluxoSelecionado(fluxo)}
            >
              <div className="flex justify-between items-center">
                <span className="font-medium text-sm">{fluxo.nome}</span>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    ativarFluxo(fluxo.id);
                  }}
                  className={`text-xs px-2 py-1 rounded ${fluxo.ativo ? 'bg-green-500 text-white' : 'bg-gray-300'}`}
                >
                  {fluxo.ativo ? 'Ativo' : 'Ativar'}
                </button>
              </div>
              <p className="text-xs text-gray-500">{fluxo.etapas} personalizações</p>
              <p className="text-xs text-gray-400">Atualizado: {fluxo.atualizado}</p>
            </li>
          ))}
        </ul>
        <button
          onClick={novoFluxo}
          className="mt-6 w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 text-sm"
        >
          ➕ Novo Fluxo
        </button>
      </aside>

      <main className="flex-1 p-6">
        <header className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-xl font-bold">Editor: {fluxoSelecionado.nome}</h1>
            <p className="text-sm text-gray-500">Última edição: {fluxoSelecionado.atualizado}</p>
          </div>
          <div className="flex gap-3">
            <button className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 text-sm">💾 Salvar</button>
            <button className="bg-gray-300 text-sm px-4 py-2 rounded hover:bg-gray-400">📥 Importar</button>
            <button className="bg-yellow-500 text-white text-sm px-4 py-2 rounded hover:bg-yellow-600">🧪 Simular</button>
          </div>
        </header>

        <div className="mb-4">
          <label className="text-sm font-medium mr-2">Modo:</label>
          <button
            onClick={() => setModoAvancado(false)}
            className={`px-4 py-2 rounded-l ${!modoAvancado ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
          >
            Visual
          </button>
          <button
            onClick={() => setModoAvancado(true)}
            className={`px-4 py-2 rounded-r ${modoAvancado ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
          >
            Avançado (JSON)
          </button>
        </div>

        {!modoAvancado ? (
          <BlocoEtapaVisual etapaId={1} />
        ) : (
          <textarea
            className="w-full border p-4 rounded h-64 bg-white text-sm font-mono"
            placeholder="Cole aqui seu fluxo em JSON"
          />
        )}
      </main>
    </div>
  );
}
